create function pg_temp.prepare(s jsonb,i jsonb) returns jsonb language sql as $$ select prepare_diagnostic_pdf_manifest('b3200000-0000-4000-8000-000000000051','b3200000-0000-4000-8000-000000000061',1,'b3200000-0000-4000-8000-000000000801',s,i) $$;
